-- retention/purge-due-contacts
-- Deletes the encrypted contact of every submission whose decision was more than 30 days ago.
--
-- Parameters, with the example values used to render this file:
--   $1 = null
--   $2 = null
--
-- Generated by `pnpm db:queries` from lib/db/queries/retention.ts. Do not edit by hand.

update "submissions"
set "contact_encrypted" = $1, "contact_purge_after" = $2
where ("submissions"."contact_encrypted" is not null
  and "submissions"."contact_purge_after" < now())
returning "id";
